    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto seq_len = q.size(2);
    auto head_dim = q.size(3);

    auto out = torch::zeros_like(q);

    dim3 grid(batch_size, num_heads, (seq_len + TILE_SIZE - 1) / TILE_SIZE);
    dim3 block(256);  // 8 warps per block

    // Launch the kernel with the default stream
    gqa_attention_kernel<<<grid, block>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        batch_size,
        num_heads,
        num_kv_heads,
        seq_len,
        head_dim,
        softmax_scale
    );

    return out;
}
